#include "upscale/scale_pass.h"

#include "core/log.h"

#include <algorithm>
#include <array>
#include <cmath>

// Compiled shader bytecode (generated by fxc at build time, see shaders/CMakeLists.txt).
#include "g_vs_fullscreen.h"
#include "g_ps_bilinear.h"
#include "g_ps_nearest.h"
#include "g_ps_bicubic.h"
#include "g_ps_lanczos.h"
#include "g_ps_sharpen.h"
#include "g_ps_moonsr_spatial.h"

using Microsoft::WRL::ComPtr;

namespace moonsr {

namespace {

// Mirror of `cbuffer ScaleConstants` in shaders/common/scale_common.hlsli.
struct ScaleConstants {
    float srcTexSize[2];
    float srcTexelSize[2];
    float srcRectOrigin[2];
    float srcRectSize[2];
    float dstSize[2];
    float dstInvSize[2];
    float sharpness;
    float param1;
    float param2;
    float param3;
};
static_assert(sizeof(ScaleConstants) == 64);

struct ShaderBlob {
    const BYTE* data = nullptr;
    size_t size = 0;
};

struct ScalerEntry {
    ScalerKind kind;
    const wchar_t* name;
    ShaderBlob ps;
};

#define MSR_BLOB(x) ShaderBlob{x, sizeof(x)}

const std::array<ScalerEntry, static_cast<size_t>(ScalerKind::Count)> kScalers = {{
    {ScalerKind::Nearest, L"Nearest", MSR_BLOB(g_ps_nearest)},
    {ScalerKind::Bilinear, L"Bilinear", MSR_BLOB(g_ps_bilinear)},
    {ScalerKind::Bicubic, L"Bicubic (Catmull-Rom)", MSR_BLOB(g_ps_bicubic)},
    {ScalerKind::Lanczos, L"Lanczos-3", MSR_BLOB(g_ps_lanczos)},
    {ScalerKind::MoonSRSpatial, L"MoonSR Spatial", MSR_BLOB(g_ps_moonsr_spatial)},
    {ScalerKind::MoonALSR, L"MoonSR (experimental)", {}},
}};

const ScalerEntry& Entry(ScalerKind kind) {
    const auto i = static_cast<size_t>(kind);
    return kScalers[i < kScalers.size() ? i : static_cast<size_t>(ScalerKind::Bilinear)];
}

class ScalePassImpl final : public ScalePass {
public:
    bool Init(GpuDevice& device, std::wstring& error) {
        dev_ = device.Device();
        ctx_ = device.Context();

        HRESULT hr = dev_->CreateVertexShader(g_vs_fullscreen, sizeof(g_vs_fullscreen), nullptr, &vs_);
        if (FAILED(hr)) return Fail(error, L"CreateVertexShader", hr);

        for (size_t i = 0; i < kScalers.size(); ++i) {
            if (!kScalers[i].ps.data) continue;
            hr = dev_->CreatePixelShader(kScalers[i].ps.data, kScalers[i].ps.size, nullptr, &ps_[i]);
            if (FAILED(hr)) return Fail(error, std::wstring(L"CreatePixelShader ") + kScalers[i].name, hr);
        }
        hr = dev_->CreatePixelShader(g_ps_sharpen, sizeof(g_ps_sharpen), nullptr, &psSharpen_);
        if (FAILED(hr)) return Fail(error, L"CreatePixelShader sharpen", hr);

        D3D11_BUFFER_DESC bd{};
        bd.ByteWidth = sizeof(ScaleConstants);
        bd.Usage = D3D11_USAGE_DYNAMIC;
        bd.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
        bd.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
        hr = dev_->CreateBuffer(&bd, nullptr, &cb_);
        if (FAILED(hr)) return Fail(error, L"CreateBuffer", hr);

        D3D11_SAMPLER_DESC sd{};
        sd.AddressU = sd.AddressV = sd.AddressW = D3D11_TEXTURE_ADDRESS_CLAMP;
        sd.MaxLOD = D3D11_FLOAT32_MAX;
        sd.MaxAnisotropy = 1;
        sd.ComparisonFunc = D3D11_COMPARISON_NEVER;
        sd.Filter = D3D11_FILTER_MIN_MAG_LINEAR_MIP_POINT;
        hr = dev_->CreateSamplerState(&sd, &linear_);
        if (FAILED(hr)) return Fail(error, L"CreateSamplerState", hr);
        sd.Filter = D3D11_FILTER_MIN_MAG_MIP_POINT;
        hr = dev_->CreateSamplerState(&sd, &point_);
        if (FAILED(hr)) return Fail(error, L"CreateSamplerState", hr);

        D3D11_RASTERIZER_DESC rd{};
        rd.FillMode = D3D11_FILL_SOLID;
        rd.CullMode = D3D11_CULL_NONE;
        rd.DepthClipEnable = TRUE;
        hr = dev_->CreateRasterizerState(&rd, &raster_);
        if (FAILED(hr)) return Fail(error, L"CreateRasterizerState", hr);
        return true;
    }

    bool Render(ID3D11Texture2D* src, const RectI& srcRectIn, ID3D11RenderTargetView* dst, Size dstSize,
                const ScaleSettings& requested, RectI* outDestRect) override {
        ScaleSettings settings = requested;
        if (!settings.enabled) { // upscaling off: exact 1:1 copy
            settings.scaler = ScalerKind::Nearest;
            settings.fit = FitMode::Native;
            settings.sharpness = 0.0f;
        }
        if (!src || !dst || dstSize.Empty()) return false;

        D3D11_TEXTURE2D_DESC srcDesc;
        src->GetDesc(&srcDesc);
        // Never trust the caller's rectangle beyond the texture: the shaders clamp to the rectangle only.
        const RectI srcRect{std::max(srcRectIn.left, 0), std::max(srcRectIn.top, 0),
                            std::min(srcRectIn.right, static_cast<int32_t>(srcDesc.Width)),
                            std::min(srcRectIn.bottom, static_cast<int32_t>(srcDesc.Height))};
        if (srcRect.Empty()) return false;

        ID3D11ShaderResourceView* srcSrv = SourceView(src);
        if (!srcSrv) return false;

        const Size srcSize{static_cast<uint32_t>(srcRect.Width()), static_cast<uint32_t>(srcRect.Height())};
        const RectI dstRect = ComputeDestRect(srcSize, dstSize, settings.fit);
        if (outDestRect) *outDestRect = dstRect;
        const Size dstRectSize{static_cast<uint32_t>(dstRect.Width()), static_cast<uint32_t>(dstRect.Height())};

        size_t scaler = static_cast<size_t>(settings.scaler);
        if (scaler >= ps_.size() || !ps_[scaler]) {
            // No shader for this kind (MoonSR temporal runs outside ScalePass, or an unknown value): best plain scaler.
            scaler = static_cast<size_t>(ScalerKind::Lanczos);
            if (!ps_[scaler]) scaler = static_cast<size_t>(ScalerKind::Bilinear);
        }

        const bool sharpen = psSharpen_ && settings.sharpness > 0.0f && settings.scaler != ScalerKind::Nearest;
        if (sharpen && !EnsureIntermediate(dstRectSize, srcDesc.Format)) return false;

        const float black[4] = {0, 0, 0, 1};
        ctx_->ClearRenderTargetView(dst, black);

        ctx_->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
        ctx_->IASetInputLayout(nullptr);
        ctx_->VSSetShader(vs_.Get(), nullptr, 0);
        ctx_->RSSetState(raster_.Get());
        ctx_->OMSetBlendState(nullptr, nullptr, 0xFFFFFFFF);
        ctx_->OMSetDepthStencilState(nullptr, 0);
        ID3D11SamplerState* samplers[2] = {linear_.Get(), point_.Get()};
        ctx_->PSSetSamplers(0, 2, samplers);
        ctx_->PSSetConstantBuffers(0, 1, cb_.GetAddressOf());

        bool ok = true;
        if (sharpen) {
            // Stage 1: scale into the intermediate at destination-rect resolution.
            const RectI full{0, 0, dstRect.Width(), dstRect.Height()};
            ok = Draw(ps_[scaler].Get(), srcSrv, Size{srcDesc.Width, srcDesc.Height}, srcRect, intermediateRtv_.Get(),
                      full, settings.sharpness);
            // Stage 2: sharpen from the intermediate into the destination rectangle (1:1).
            ok = ok && Draw(psSharpen_.Get(), intermediateSrv_.Get(), dstRectSize, full, dst, dstRect, settings.sharpness);
        } else {
            ok = Draw(ps_[scaler].Get(), srcSrv, Size{srcDesc.Width, srcDesc.Height}, srcRect, dst, dstRect,
                      settings.sharpness);
        }

        ID3D11ShaderResourceView* nullSrv = nullptr;
        ctx_->PSSetShaderResources(0, 1, &nullSrv);
        ID3D11RenderTargetView* nullRtv = nullptr;
        ctx_->OMSetRenderTargets(1, &nullRtv, nullptr);
        return ok;
    }

    void ResetSourceCache() override { srcCache_.clear(); }

private:
    static bool Fail(std::wstring& error, const std::wstring& what, HRESULT hr) {
        error = L"ScalePass: " + what + L" failed: " + HrToString(hr);
        MSR_LOG_ERROR(L"{}", error);
        return false;
    }

    bool Draw(ID3D11PixelShader* ps, ID3D11ShaderResourceView* srv, Size srcTexSize, const RectI& srcRect,
              ID3D11RenderTargetView* rtv, const RectI& dstRect, float sharpness) {
        D3D11_MAPPED_SUBRESOURCE map;
        const HRESULT hr = ctx_->Map(cb_.Get(), 0, D3D11_MAP_WRITE_DISCARD, 0, &map);
        if (FAILED(hr)) {
            MSR_LOG_ERROR(L"ScalePass: Map failed: {}", HrToString(hr));
            return false;
        }
        ScaleConstants c{};
        c.srcTexSize[0] = static_cast<float>(srcTexSize.width);
        c.srcTexSize[1] = static_cast<float>(srcTexSize.height);
        c.srcTexelSize[0] = 1.0f / c.srcTexSize[0];
        c.srcTexelSize[1] = 1.0f / c.srcTexSize[1];
        c.srcRectOrigin[0] = static_cast<float>(srcRect.left);
        c.srcRectOrigin[1] = static_cast<float>(srcRect.top);
        c.srcRectSize[0] = static_cast<float>(srcRect.Width());
        c.srcRectSize[1] = static_cast<float>(srcRect.Height());
        c.dstSize[0] = static_cast<float>(dstRect.Width());
        c.dstSize[1] = static_cast<float>(dstRect.Height());
        c.dstInvSize[0] = 1.0f / c.dstSize[0];
        c.dstInvSize[1] = 1.0f / c.dstSize[1];
        c.sharpness = std::clamp(sharpness, 0.0f, 1.0f);
        memcpy(map.pData, &c, sizeof(c));
        ctx_->Unmap(cb_.Get(), 0);

        D3D11_VIEWPORT vp{};
        vp.TopLeftX = static_cast<float>(dstRect.left);
        vp.TopLeftY = static_cast<float>(dstRect.top);
        vp.Width = static_cast<float>(dstRect.Width());
        vp.Height = static_cast<float>(dstRect.Height());
        vp.MaxDepth = 1.0f;
        ctx_->RSSetViewports(1, &vp);
        ctx_->OMSetRenderTargets(1, &rtv, nullptr);
        ctx_->PSSetShader(ps, nullptr, 0);
        ctx_->PSSetShaderResources(0, 1, &srv);
        ctx_->Draw(3, 0);
        return true;
    }

    // Capture APIs hand out a small rotating pool of textures; cache one SRV per texture to avoid per-frame allocations.
    ID3D11ShaderResourceView* SourceView(ID3D11Texture2D* tex) {
        for (auto& e : srcCache_)
            if (e.tex.Get() == tex) return e.srv.Get();
        if (srcCache_.size() >= 12) srcCache_.clear();
        SrcEntry e;
        e.tex = tex;
        const HRESULT hr = dev_->CreateShaderResourceView(tex, nullptr, &e.srv);
        if (FAILED(hr)) {
            MSR_LOG_ERROR(L"ScalePass: CreateShaderResourceView(source) failed: {}", HrToString(hr));
            return nullptr;
        }
        srcCache_.push_back(std::move(e));
        return srcCache_.back().srv.Get();
    }

    bool EnsureIntermediate(Size size, DXGI_FORMAT format) {
        if (intermediate_ && intermediateSize_ == size && intermediateFormat_ == format) return true;
        intermediate_.Reset();
        intermediateRtv_.Reset();
        intermediateSrv_.Reset();
        D3D11_TEXTURE2D_DESC td{};
        td.Width = size.width;
        td.Height = size.height;
        td.MipLevels = 1;
        td.ArraySize = 1;
        td.Format = format;
        td.SampleDesc.Count = 1;
        td.Usage = D3D11_USAGE_DEFAULT;
        td.BindFlags = D3D11_BIND_RENDER_TARGET | D3D11_BIND_SHADER_RESOURCE;
        HRESULT hr = dev_->CreateTexture2D(&td, nullptr, &intermediate_);
        if (SUCCEEDED(hr)) hr = dev_->CreateRenderTargetView(intermediate_.Get(), nullptr, &intermediateRtv_);
        if (SUCCEEDED(hr)) hr = dev_->CreateShaderResourceView(intermediate_.Get(), nullptr, &intermediateSrv_);
        if (FAILED(hr)) {
            MSR_LOG_ERROR(L"ScalePass: intermediate target {}x{} failed: {}", size.width, size.height, HrToString(hr));
            intermediate_.Reset();
            return false;
        }
        intermediateSize_ = size;
        intermediateFormat_ = format;
        return true;
    }

    struct SrcEntry {
        ComPtr<ID3D11Texture2D> tex;
        ComPtr<ID3D11ShaderResourceView> srv;
    };

    ID3D11Device1* dev_ = nullptr;
    ID3D11DeviceContext1* ctx_ = nullptr;
    ComPtr<ID3D11VertexShader> vs_;
    std::array<ComPtr<ID3D11PixelShader>, static_cast<size_t>(ScalerKind::Count)> ps_;
    ComPtr<ID3D11PixelShader> psSharpen_;
    ComPtr<ID3D11Buffer> cb_;
    ComPtr<ID3D11SamplerState> linear_;
    ComPtr<ID3D11SamplerState> point_;
    ComPtr<ID3D11RasterizerState> raster_;
    std::vector<SrcEntry> srcCache_;
    ComPtr<ID3D11Texture2D> intermediate_;
    ComPtr<ID3D11RenderTargetView> intermediateRtv_;
    ComPtr<ID3D11ShaderResourceView> intermediateSrv_;
    Size intermediateSize_;
    DXGI_FORMAT intermediateFormat_ = DXGI_FORMAT_UNKNOWN;
};

} // namespace

std::unique_ptr<ScalePass> ScalePass::Create(GpuDevice& device, std::wstring& error) {
    auto p = std::make_unique<ScalePassImpl>();
    if (!p->Init(device, error)) return nullptr;
    return p;
}

std::vector<ScalerDesc> ScalePass::ListScalers() {
    std::vector<ScalerDesc> out;
    for (const auto& e : kScalers) out.push_back({e.kind, e.name, e.ps.data != nullptr});
    return out;
}

const wchar_t* ScalePass::ScalerName(ScalerKind kind) { return Entry(kind).name; }

RectI ScalePass::ComputeDestRect(Size src, Size dst, FitMode fit) {
    if (src.Empty() || dst.Empty()) return {};
    double w = dst.width, h = dst.height;
    if (fit == FitMode::Native) {
        // 1:1 when it fits; a source larger than the output is aspect-fitted instead.
        if (src.width <= dst.width && src.height <= dst.height) {
            const int32_t x = static_cast<int32_t>(dst.width - src.width) / 2;
            const int32_t y = static_cast<int32_t>(dst.height - src.height) / 2;
            return {x, y, x + static_cast<int32_t>(src.width), y + static_cast<int32_t>(src.height)};
        }
        fit = FitMode::Fit;
    }
    switch (fit) {
    case FitMode::Stretch:
        break;
    case FitMode::Integer: {
        const uint32_t k = std::max<uint32_t>(1, std::min(dst.width / src.width, dst.height / src.height));
        w = static_cast<double>(src.width) * k;
        h = static_cast<double>(src.height) * k;
        // A source larger than the output cannot be integer scaled; fall back to aspect fit.
        if (w <= dst.width && h <= dst.height) break;
        [[fallthrough]];
    }
    case FitMode::Fit:
    default: {
        const double s = std::min(static_cast<double>(dst.width) / src.width, static_cast<double>(dst.height) / src.height);
        w = std::round(src.width * s);
        h = std::round(src.height * s);
        break;
    }
    }
    const int32_t iw = std::clamp(static_cast<int32_t>(w), 1, static_cast<int32_t>(dst.width));
    const int32_t ih = std::clamp(static_cast<int32_t>(h), 1, static_cast<int32_t>(dst.height));
    const int32_t x = (static_cast<int32_t>(dst.width) - iw) / 2;
    const int32_t y = (static_cast<int32_t>(dst.height) - ih) / 2;
    return {x, y, x + iw, y + ih};
}

} // namespace moonsr
